INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um homem de 45 anos, motorista de carga pesada, apresenta-se ao ambulatório com queixa de dor lombar intensa que se irradia para a face lateral da perna esquerda e dorso do pé. Durante o exame físico, observa-se diminuição da força na dorsiflexão do hálux e sensibilidade alterada no primeiro espaço interdigital. Ao revisar a anatomia da coluna vertebral, o médico identifica que a hérnia de disco provável está comprimindo uma raiz nervosa que emerge abaixo da vértebra correspondente. Considerando as características anatômicas das vértebras lombares e a emergência das raízes nervosas, assinale a alternativa que descreve corretamente a relação anatômica envolvida.","options":{"a":"A raiz de L5 emerge pelo forame intervertebral entre L5 e S1, sendo tipicamente comprimida por uma hérnia discal nesse nível.","b":"As vértebras lombares possuem forames transversários que protegem a passagem das raízes nervosas antes de sua saída pelo forame intervertebral.","c":"O processo espinhoso das vértebras lombares é delgado e inclinado inferiormente, dificultando o acesso cirúrgico posterior ao canal vertebral.","d":"O ligamento amarelo conecta os processos transversos de vértebras adjacentes, servindo como limite anterior do forame intervertebral.","e":"O canal vertebral no nível lombar é circular e estreito, o que predispõe à síndrome da cauda equina em casos de protusões centrais mínimas."},"answer":"a","rationale":"A questão aborda a anatomia aplicada da coluna lombar. No nível lombar, as raízes nervosas emergem abaixo da vértebra de mesma numeração. A sintomatologia descrita (fraqueza na dorsiflexão do hálux e parestesia no dorso do pé) é clássica de compressão da raiz de L5. A raiz de L5 sai pelo forame entre L5 e S1. Portanto, a alternativa A reflete corretamente a anatomia de emergência nervosa e a correlação clínica habitual das hérnias discais posterolaterais.","option_rationales":{"a":"Correta. A emergência das raízes lombares ocorre logo abaixo do pedículo da vértebra correspondente.","b":"Errada. Forames transversários são características exclusivas das vértebras cervicais (passagem da artéria vertebral).","c":"Errada. O processo espinhoso lombar é quadrilátero, robusto e horizontalizado.","d":"Errada. O ligamento amarelo conecta as lâminas das vértebras, não os processos transversos; o limite anterior do forame é o disco e o corpo vertebral.","e":"Errada. O canal vertebral lombar tende a ser triangular; protusões \"mínimas\" raramente causam síndrome da cauda equina, que exige compressão volumosa."},"difficulty":"Média","tags":["Anatomia","Coluna Vertebral","Neuroanatomia Aplicada"]}', '4bac0f35abc0baa98369536c9c9914fd', 0, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Durante uma cirurgia de correção de hérnia inguinal por via aberta (técnica de Lichtenstein), o cirurgião precisa identificar as estruturas que compõem o canal inguinal para posicionar a tela adequadamente. Ao dissecar a região, identifica-se uma camada aponeurótica que forma a parede anterior do canal em quase toda a sua extensão e cujo bordo inferior se enrola para formar o ligamento inguinal. Essa estrutura anatômica é derivada de qual dos seguintes músculos ou aponeuroses?","options":{"a":"Músculo transverso do abdome.","b":"Aponeurose do músculo oblíquo externo.","c":"Fáscia transversalis.","d":"Músculo oblíquo interno.","e":"Músculo reto abdominal."},"answer":"b","rationale":"O canal inguinal é uma passagem oblíqua através da parede abdominal. A parede anterior é formada primordialmente pela aponeurose do músculo oblíquo externo do abdome. O ligamento inguinal (de Poupart) é, de fato, o bordo inferior espessado e fletido dessa aponeurose, estendendo-se da espinha ilíaca anterossuperior ao tubérculo púbico. O conhecimento dessas camadas é fundamental para a técnica cirúrgica de reparo de hérnias.","option_rationales":{"a":"Errada. O transverso do abdome forma a parede posterior (via tendão conjunto) e o teto do canal, mas não a parede anterior.","b":"Correta. A aponeurose do oblíquo externo forma a parede anterior e o ligamento inguinal.","c":"Errada. A fáscia transversalis forma a parede posterior do canal inguinal.","d":"Errada. O oblíquo interno contribui para o teto do canal e, em conjunto com o transverso, forma o foice inguinal (tendão conjunto).","e":"Errada. O músculo reto abdominal situa-se medialmente ao canal inguinal e não compõe suas paredes diretas."},"difficulty":"Média","tags":["Anatomia","Parede Abdominal","Canal Inguinal"]}', 'dbb6249eb49d7634c129d95aec94c379', 1, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um paciente vítima de trauma torácico fechado apresenta fratura de múltiplas costelas, resultando em um quadro de tórax instável. Durante a avaliação radiológica, nota-se que a fratura ocorreu na região mais frágil da costela, onde o osso apresenta sua maior curvatura e o sulco costal é mais evidente. Além disso, o médico deve estar atento ao feixe vasculonervoso intercostal. Com base na anatomia das costelas típicas, assinale a alternativa que descreve corretamente a localização do feixe vasculonervoso intercostal.","options":{"a":"O feixe localiza-se na borda superior da costela, protegido pelo músculo intercostal externo.","b":"O feixe localiza-se na borda inferior da costela, no sulco da costela, entre os músculos intercostal interno e íntimo.","c":"O feixe localiza-se superficialmente ao músculo intercostal externo, logo abaixo da fáscia peitoral.","d":"O nervo intercostal situa-se superiormente à artéria e à veia dentro do sulco costal.","e":"A veia intercostal é a estrutura mais inferior do feixe, sendo a primeira a ser lesada em punções inadvertidas na borda inferior."},"answer":"b","rationale":"As costelas típicas (3ª a 9ª) possuem um sulco na face interna de sua borda inferior. O feixe vasculonervoso intercostal (Veia, Artéria, Nervo - mnemônico VAN) percorre esse sulco. Anatômica e cirurgicamente, o feixe situa-se no plano entre as camadas média (intercostal interno) e profunda (intercostal íntimo) dos músculos intercostais. Por isso, orienta-se realizar punções torácicas na borda SUPERIOR da costela inferior ao espaço, para evitar lesão do feixe.","option_rationales":{"a":"Errada. O feixe situa-se na borda inferior, não na superior.","b":"Correta. Esta é a descrição clássica da topografia do feixe VAN intercostal.","c":"Errada. O feixe é profundo aos músculos intercostais externo e interno.","d":"Errada. A ordem de superior para inferior é Veia, Artéria e Nervo (VAN); o nervo é o mais inferior.","e":"Errada. O nervo é a estrutura mais inferior do feixe, não a veia."},"difficulty":"Média","tags":["Anatomia","Tórax","Osteologia"]}', '9b9a82fa978dd4f27c776cb26283df9c', 2, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O diafragma é o principal músculo da respiração e separa as cavidades torácica e abdominal. Ele possui hiatos que permitem a passagem de estruturas fundamentais entre essas cavidades. Um paciente com esofagite de refluxo grave apresenta hérnia de hiato ao exame endoscópico. Anatômica e funcionalmente, o hiato esofágico é formado predominantemente por fibras de qual estrutura?","options":{"a":"Pilar direito do diafragma.","b":"Pilar esquerdo do diafragma.","c":"Centro tendíneo do diafragma.","d":"Ligamento arqueado mediano.","e":"Ligamento arqueado lateral."},"answer":"a","rationale":"O diafragma possui três grandes aberturas: o forame da veia cava (no centro tendíneo, nível T8), o hiato esofágico (nível T10) e o hiato aórtico (nível T12). O hiato esofágico é formado por uma fenda muscular nas fibras do pilar direito do diafragma, que se cruzam para formar uma espécie de esfíncter extrínseco ao redor do esôfago. Fraquezas nessas fibras contribuem para o desenvolvimento de hérnias de hiato.","option_rationales":{"a":"Correta. O pilar direito circunda o esôfago na maioria dos indivíduos.","b":"Errada. O pilar esquerdo é menor e raramente contribui significativamente para a formação do hiato esofágico.","c":"Errada. O centro tendíneo abriga o forame da veia cava, não o hiato esofágico.","d":"Errada. O ligamento arqueado mediano forma o arco anterior do hiato aórtico.","e":"Errada. O ligamento arqueado lateral é um espessamento da fáscia do músculo quadrado lombar e não forma hiatos viscerais."},"difficulty":"Média","tags":["Anatomia","Diafragma","Sistema Digestório"]}', '15915cc748c81f9d62c303590d4dcd16', 3, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Durante um exame físico de rotina, um médico solicita que o paciente realize uma inspiração profunda forçada. Ele observa a contração dos músculos acessórios da respiração. Entre os músculos citados abaixo, qual deles atua como um músculo inspiratório acessório ao elevar as primeiras e segundas costelas?","options":{"a":"Músculos escalenos.","b":"Músculo reto abdominal.","c":"Músculo transverso do tórax.","d":"Músculos intercostais internos (parte interóssea).","e":"Músculo oblíquo externo."},"answer":"a","rationale":"Na inspiração forçada ou em situações de insuficiência respiratória, músculos acessórios são recrutados para aumentar o volume da caixa torácica. Os músculos escalenos (anterior, médio e posterior), localizados no pescoço, fixam-se no processo transverso das vértebras cervicais e inserem-se na 1ª e 2ª costelas. Sua contração eleva essas costelas, auxiliando na expansão do diâmetro superior do tórax.","option_rationales":{"a":"Correta. Os escalenos elevam as costelas superiores.","b":"Errada. O reto abdominal é um potente músculo expiratório acessório (comprime as vísceras e abaixa as costelas).","c":"Errada. O transverso do tórax auxilia no abaixamento das cartilagens costais (expiração).","d":"Errada. A parte interóssea dos intercostais internos atua na expiração forçada; apenas a parte intercondral auxilia na inspiração.","e":"Errada. O oblíquo externo é um músculo expiratório acessório."},"difficulty":"Fácil","tags":["Anatomia","Músculos","Sistema Respiratório"]}', 'a56fe12d3fc01d76f5ff360331bd1cc0', 4, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A articulação atlantoaxial é responsável por grande parte da amplitude de movimento de rotação da cabeça. Ela é composta por articulações sinoviais entre o atlas (C1) e o áxis (C2). O dente do áxis é a estrutura central desse movimento, sendo mantido em posição contra o arco anterior do atlas por um ligamento crucial para a estabilidade da coluna cervical superior. Em casos de artrite reumatoide grave, esse ligamento pode sofrer erosão, levando à subluxação atlantoaxial perigosa. Qual é esse ligamento?","options":{"a":"Ligamento alar.","b":"Ligamento transverso do atlas.","c":"Ligamento amarelo.","d":"Ligamento nucal.","e":"Ligamento longitudinal anterior."},"answer":"b","rationale":"O ligamento transverso do atlas estende-se entre os tubérculos nas massas laterais de C1, passando posteriormente ao dente do áxis. Ele forma a parede posterior da articulação trocoide atlantoaxial mediana. Sua integridade impede que o dente se desloque para trás e comprima a medula espinal. Ligamentos alares limitam a rotação, mas o transverso é o principal estabilizador \"em pivô\".","option_rationales":{"a":"Errada. Os ligamentos alares unem o dente aos côndilos occipitais e limitam a rotação lateral excessiva.","b":"Correta. O ligamento transverso é o pilar da estabilidade atlantoaxial mediana.","c":"Errada. O ligamento amarelo está presente entre as lâminas de todas as vértebras abaixo de C1.","d":"Errada. O ligamento nucal é um septo fibroso posterior que se estende da protuberância occipital externa aos processos espinhosos cervicais.","e":"Errada. O ligamento longitudinal anterior percorre a face anterior dos corpos vertebrais; ele não estabiliza o dente do áxis especificamente."},"difficulty":"Média","tags":["Anatomia","Artrologia","Coluna Vertebral"]}', '370717706e8a08eb63bb2e7d1a3e2f46', 5, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um estudante de medicina observa, durante a dissecação de um cadáver, uma estrutura fibrosa que corre verticalmente na linha média da parede abdominal anterior, estendendo-se do processo xifoide à sínfise púbica. Ele nota que essa estrutura é formada pela decussação das aponeuroses dos músculos oblíquo externo, oblíquo interno e transverso do abdome. Sabendo que essa região é um local comum para a realização de laparotomias por ser relativamente avascular, identifique a estrutura descrita.","options":{"a":"Linha semilunar.","b":"Fáscia de Scarpa.","c":"Linha alba.","d":"Bainha do músculo reto.","e":"Ligamento de Cooper."},"answer":"c","rationale":"A linha alba é o rafe fibroso central da parede abdominal anterior. Ela resulta do entrelaçamento das fibras aponeuróticas dos músculos largos do abdome de ambos os lados. Como contém poucos vasos sanguíneos e nervos significativos, é a via de escolha para a incisão mediana (laparotomia mediana), facilitando o acesso rápido e com sangramento mínimo à cavidade peritoneal.","option_rationales":{"a":"Errada. A linha semilunar marca o limite lateral do músculo reto abdominal.","b":"Errada. A fáscia de Scarpa é uma camada profunda e membranosa da tela subcutânea abdominal.","c":"Correta. Descrição clássica da linha alba abdominal.","d":"Errada. A bainha do músculo reto é o invólucro aponeurótico do músculo reto, mas a estrutura central é a linha alba.","e":"Errada. O ligamento de Cooper (pectíneo) localiza-se na crista pectínea do púbis."},"difficulty":"Fácil","tags":["Anatomia","Parede Abdominal","Músculos"]}', '699cefcb4abe1a5ed2a0669c0ffb22a9', 6, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A parede torácica é suprida por artérias intercostais que se anastomosam para garantir a perfusão dos tecidos. A maioria das artérias intercostais posteriores origina-se diretamente da aorta torácica. No entanto, as duas primeiras artérias intercostais posteriores originam-se de um tronco comum. Identifique a origem correta das artérias intercostais posteriores do 1º e 2º espaços.","options":{"a":"Artéria mamária interna (torácica interna).","b":"Artéria intercostal suprema, ramo do tronco costocervical.","c":"Artéria subclávia, ramo direto.","d":"Artéria carótida comum.","e":"Artéria axilar, ramo torácico superior."},"answer":"b","rationale":"O suprimento arterial das paredes torácicas é distribuído entre artérias intercostais anteriores (ramos da torácica interna) e posteriores. As intercostais posteriores do 3º ao 11º espaço nascem da aorta. Já as dos dois primeiros espaços derivam da artéria intercostal suprema, que por sua vez é um ramo do tronco costocervical, um dos ramos da segunda porção da artéria subclávia. Esse detalhe é frequente em provas de anatomia vascular.","option_rationales":{"a":"Errada. A torácica interna dá origem às intercostais anteriores.","b":"Correta. A intercostal suprema supre os dois primeiros espaços posteriores.","c":"Errada. Não nascem diretamente da subclávia, mas via tronco costocervical.","d":"Errada. A carótida comum supre cabeça e pescoço.","e":"Errada. A torácica superior supre a parte superior da parede torácica, mas não as intercostais posteriores típicas."},"difficulty":"Difícil","tags":["Anatomia","Vascularização","Tórax"]}', '013e151d735353d9abfa6db9b811c217', 7, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um paciente de 60 anos apresenta dificuldade progressiva para defecar e dor na região perineal. O exame físico revela uma hérnia que protrui através de uma fraqueza no assoalho pélvico. Anatomia básica: o assoalho pélvico (diafragma da pélvis) é formado primordialmente por um complexo muscular que sustenta as vísceras pélvicas. Qual é o principal músculo desse complexo?","options":{"a":"Músculo piriforme.","b":"Músculo levantador do ânus.","c":"Músculo obturador interno.","d":"Músculo psoas maior.","e":"Músculo glúteo máximo."},"answer":"b","rationale":"O diafragma da pélvis é a estrutura muscular que fecha a abertura inferior da pélvis. Ele é composto principalmente pelo músculo levantador do ânus (formado pelos músculos puborretal, pubococcígeo e iliococcígeo) e pelo músculo isquiococcígeo (coccígeo). O levantador do ânus é essencial para a continência fecal e urinária, além de sustentar o útero, bexiga e reto.","option_rationales":{"a":"Errada. O piriforme é um músculo da parede posterior da pélvis que atua no quadril.","b":"Correta. O levantador do ânus é o principal componente do assoalho pélvico.","c":"Errada. O obturador interno forma a parede lateral da pélvis menor.","d":"Errada. O psoas maior localiza-se na parede abdominal posterior.","e":"Errada. O glúteo máximo é um músculo extrínseco da região glútea."},"difficulty":"Média","tags":["Anatomia","Pélvis","Assoalho Pélvico"]}', 'b3946646d8ce6cc0d4667aabd042c1bd', 8, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Durante uma punção lombar (colheita de líquor), a agulha deve atravessar várias camadas de tecido antes de atingir o espaço subaracnóideo. Após atravessar a pele e o tecido subcutâneo na linha média entre os processos espinhosos de L3 e L4, qual é a sequência correta dos ligamentos perfurados pela agulha até chegar à dura-máter?","options":{"a":"Ligamento supraespinal → Ligamento infraespinal → Ligamento amarelo.","b":"Ligamento supraespinal → Ligamento interespinal → Ligamento amarelo.","c":"Ligamento interespinal → Ligamento supraespinal → Ligamento longitudinal posterior.","d":"Ligamento longitudinal anterior → Ligamento amarelo → Ligamento interespinal.","e":"Ligamento nucal → Ligamento interespinal → Ligamento amarelo."},"answer":"b","rationale":"Para realizar uma punção lombar mediana, a agulha percorre: Pele → Subcutâneo → Ligamento supraespinal (que conecta as pontas dos processos espinhosos) → Ligamento interespinal (entre os processos espinhosos) → Ligamento amarelo (entre as lâminas). Ao perfurar o ligamento amarelo, sente-se frequentemente uma \"perda de resistência\". Após o ligamento amarelo e o espaço epidural, a agulha perfura a dura-máter e a aracnóide para colher o líquor.","option_rationales":{"a":"Errada. \"Infraespinal\" não é a nomenclatura anatômica padrão para o ligamento interespinal.","b":"Correta. Sequência exata dos ligamentos de posterior para anterior na linha média.","c":"Errada. O supraespinal é mais superficial que o interespinal; o longitudinal posterior é anterior à medula.","d":"Errada. O longitudinal anterior é a estrutura mais anterior da coluna, não sendo perfurado na punção posterior.","e":"Errada. O ligamento nucal existe apenas na região cervical."},"difficulty":"Média","tags":["Anatomia","Coluna Vertebral","Prática Clínica"]}', '0e1d07a0028dc8a26eb11eccc4be0fcc', 9, 'draft');